stat.health := F_HealthStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isGood := (NOT(stat.init = InitializationStatus.initializingFailed)) AND (isTelConnected AND (isAccConnected AND (((proc.initialize.stat.health = HealthStatus.good) OR (proc.initialize.stat.health = HealthStatus.warning)) AND (((proc.changeOperatingState.stat.health = HealthStatus.good) OR (proc.changeOperatingState.stat.health = HealthStatus.warning)) AND (((proc.slewToCoordinates.stat.health = HealthStatus.good) OR (proc.slewToCoordinates.stat.health = HealthStatus.warning)) AND (((proc.slewToAziEle.stat.health = HealthStatus.good) OR (proc.slewToAziEle.stat.health = HealthStatus.warning)) AND (((proc.abortSlew.stat.health = HealthStatus.good) OR (proc.abortSlew.stat.health = HealthStatus.warning)) AND (((proc.powerOn.stat.health = HealthStatus.good) OR (proc.powerOn.stat.health = HealthStatus.warning)) AND (((proc.powerOff.stat.health = HealthStatus.good) OR (proc.powerOff.stat.health = HealthStatus.warning)) AND (((proc.moveKnownPosition.stat.health = HealthStatus.good) OR (proc.moveKnownPosition.stat.health = HealthStatus.warning)) AND (((proc.setTracking.stat.health = HealthStatus.good) OR (proc.setTracking.stat.health = HealthStatus.warning)) AND (((proc.moveM2.stat.health = HealthStatus.good) OR (proc.moveM2.stat.health = HealthStatus.warning)) AND (((proc.openCover.stat.health = HealthStatus.good) OR (proc.openCover.stat.health = HealthStatus.warning)) AND ((proc.closeCover.stat.health = HealthStatus.good) OR (proc.closeCover.stat.health = HealthStatus.warning))))))))))))))),
    hasWarning := (proc.initialize.stat.health = HealthStatus.warning) OR ((proc.changeOperatingState.stat.health = HealthStatus.warning) OR ((proc.slewToCoordinates.stat.health = HealthStatus.warning) OR ((proc.slewToAziEle.stat.health = HealthStatus.warning) OR ((proc.abortSlew.stat.health = HealthStatus.warning) OR ((proc.powerOn.stat.health = HealthStatus.warning) OR ((proc.powerOff.stat.health = HealthStatus.warning) OR ((proc.moveKnownPosition.stat.health = HealthStatus.warning) OR ((proc.setTracking.stat.health = HealthStatus.warning) OR ((proc.moveM2.stat.health = HealthStatus.warning) OR ((proc.openCover.stat.health = HealthStatus.warning) OR (proc.closeCover.stat.health = HealthStatus.warning))))))))))));
stat.busy := F_BusyStatus(
    superState := NOT(stat.init = InitializationStatus.shutdown),
    isBusy := (proc.initialize.stat.busy = BusyStatus.busy) OR ((proc.changeOperatingState.stat.busy = BusyStatus.busy) OR ((proc.slewToCoordinates.stat.busy = BusyStatus.busy) OR ((proc.slewToAziEle.stat.busy = BusyStatus.busy) OR ((proc.abortSlew.stat.busy = BusyStatus.busy) OR ((proc.powerOn.stat.busy = BusyStatus.busy) OR ((proc.powerOff.stat.busy = BusyStatus.busy) OR ((proc.moveKnownPosition.stat.busy = BusyStatus.busy) OR ((proc.setTracking.stat.busy = BusyStatus.busy) OR ((proc.moveM2.stat.busy = BusyStatus.busy) OR ((proc.openCover.stat.busy = BusyStatus.busy) OR (proc.closeCover.stat.busy = BusyStatus.busy))))))))))));
proc.initialize( isEnabled := (NOT(stat.init = InitializationStatus.locked)) AND ((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR (stat.init = InitializationStatus.initialized))) );
proc.lock( isEnabled := operator_ref = OperatorStatus.tech );
proc.unlock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );
proc.changeOperatingState( isEnabled := (stat.busy = BusyStatus.idle) AND ((stat.init = InitializationStatus.initialized) AND (operator_ref = OperatorStatus.tech)) );
proc.slewToCoordinates( isEnabled := (stat.init = InitializationStatus.initialized) AND ((stat.busy = BusyStatus.idle) AND (stat.powered = PoweredStatus.enabled)) );
proc.slewToAziEle( isEnabled := (stat.init = InitializationStatus.initialized) AND ((stat.busy = BusyStatus.idle) AND (stat.powered = PoweredStatus.enabled)) );
proc.syncToCoordinates( isEnabled := (stat.init = InitializationStatus.initialized) AND ((stat.busy = BusyStatus.idle) AND (stat.powered = PoweredStatus.enabled)) );
proc.syncToAziEle( isEnabled := (stat.init = InitializationStatus.initialized) AND ((stat.busy = BusyStatus.idle) AND (stat.powered = PoweredStatus.enabled)) );
proc.syncToTarget( isEnabled := (stat.init = InitializationStatus.initialized) AND ((stat.busy = BusyStatus.idle) AND (stat.powered = PoweredStatus.enabled)) );
proc.selectNasmythPort( isEnabled := stat.init = InitializationStatus.initialized );
proc.abortSlew( isEnabled := stat.init = InitializationStatus.initialized );
proc.reset( isEnabled := (stat.busy = BusyStatus.idle) AND (stat.init = InitializationStatus.initialized) );
proc.powerOn( isEnabled := (NOT(stat.init = InitializationStatus.locked)) AND ((stat.init = InitializationStatus.initialized) AND (proc.powerOn.stat.busy = BusyStatus.idle)) );
proc.powerOff( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.powerOff.stat.busy = BusyStatus.idle) );
proc.moveKnownPosition( isEnabled := (stat.init = InitializationStatus.initialized) AND ((stat.busy = BusyStatus.idle) AND (stat.powered = PoweredStatus.enabled)) );
proc.setTracking( isEnabled := stat.init = InitializationStatus.initialized );
proc.moveM2( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.moveM2.stat.busy = BusyStatus.idle) );
proc.openCover( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.openCover.stat.busy = BusyStatus.idle) );
proc.closeCover( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.closeCover.stat.busy = BusyStatus.idle) );
proc.pulseGuide( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.pulseGuide.stat.busy = BusyStatus.idle) );
proc.guideRateAlpha( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.guideRateAlpha.stat.busy = BusyStatus.idle) );
proc.guideRateDelta( isEnabled := (stat.init = InitializationStatus.initialized) AND (proc.guideRateDelta.stat.busy = BusyStatus.idle) );

IF do_request THEN
    do_request_result := request(
    azimuth := set.azimuth,
    elevation := set.elevation);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.azimuth := azimuth;
THIS^.get.elevation := elevation;
THIS^.stat.busy := BusyStatus.busy;
THIS^.stat.health := HealthStatus.good;

IF THIS^.stat.enabled = EnabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        azimuth := azimuth,
        elevation := elevation);
ELSE
    request := RequestResults.REJECTED;
END_IF;

